package datekit

import (
	"testing"
	"time"
)

func TestSimple(t *testing.T) {
	d := time.Date(2025, 3, 15, 10, 0, 0, 0, time.UTC)
	if got := AddMonths(d, 2); got.Month() != time.May || got.Day() != 15 {
		t.Fatalf("got %v", got)
	}
	if Quarter(d) != 1 || DaysIn(2025, time.April) != 30 {
		t.Fatal("quarter or days")
	}
}
